import { Post, examplePosts, EssayPost, MoviePost, ImagePost, CarouselPost } from '../data/posts';

// We'll use localStorage to persist post changes in this example
// In a real application, this would be replaced with API calls

const STORAGE_KEY = 'alien_posts';

// Helper to initialize posts from localStorage or use example posts
function getStoredPosts(): Post[] {
  const storedPosts = localStorage.getItem(STORAGE_KEY);
  if (storedPosts) {
    try {
      return JSON.parse(storedPosts);
    } catch (error) {
      console.error('Error parsing stored posts:', error);
      return [...examplePosts];
    }
  }
  return [...examplePosts]; // Return a copy to avoid modifying the original
}

// Helper to save posts to localStorage
function savePostsToStorage(posts: Post[]): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(posts));
}

// Get all posts
export function getAllPosts(): Post[] {
  return getStoredPosts();
}

// Get post by ID
export function getPostById(id: string): Post | undefined {
  const posts = getStoredPosts();
  return posts.find(post => post.id === id);
}

// Get posts by category ID
export function getPostsByCategoryId(categoryId: string): Post[] {
  const posts = getStoredPosts();
  return posts.filter(post => post.categoryId === categoryId);
}

// Create a new post
export function createPost(post: Omit<Post, 'id' | 'votes'>): Post {
  const posts = getStoredPosts();

  // Generate a new ID
  const newId = Date.now().toString();

  // Create the full post with default votes
  const newPost: Post = {
    ...post as any, // TypeScript needs this, we'll ensure correct type below
    id: newId,
    votes: 0
  };

  // Ensure we have the correct type properties
  switch (post.type) {
    case 'essay':
      (newPost as EssayPost).content = (post as Omit<EssayPost, 'id' | 'votes'>).content;
      break;
    case 'movie':
      (newPost as MoviePost).videoUrl = (post as Omit<MoviePost, 'id' | 'votes'>).videoUrl;
      (newPost as MoviePost).description = (post as Omit<MoviePost, 'id' | 'votes'>).description;
      break;
    case 'image':
      (newPost as ImagePost).imageUrl = (post as Omit<ImagePost, 'id' | 'votes'>).imageUrl;
      (newPost as ImagePost).description = (post as Omit<ImagePost, 'id' | 'votes'>).description;
      break;
    case 'carousel':
      (newPost as CarouselPost).images = (post as Omit<CarouselPost, 'id' | 'votes'>).images;
      break;
  }

  // Save to storage
  posts.push(newPost);
  savePostsToStorage(posts);

  return newPost;
}

// Update an existing post
export function updatePost(updatedPost: Post): Post | null {
  const posts = getStoredPosts();
  const index = posts.findIndex(post => post.id === updatedPost.id);

  if (index === -1) {
    return null;
  }

  posts[index] = updatedPost;
  savePostsToStorage(posts);

  return updatedPost;
}

// Delete a post
export function deletePost(id: string): boolean {
  const posts = getStoredPosts();
  const filteredPosts = posts.filter(post => post.id !== id);

  if (filteredPosts.length === posts.length) {
    return false; // Post not found
  }

  savePostsToStorage(filteredPosts);
  return true;
}

// Vote on a post
export function votePost(id: string, increment: boolean = true): Post | null {
  const posts = getStoredPosts();
  const index = posts.findIndex(post => post.id === id);

  if (index === -1) {
    return null;
  }

  // Increment or decrement votes
  posts[index].votes += increment ? 1 : -1;
  savePostsToStorage(posts);

  return posts[index];
}
